\documentclass{article}
\usepackage{pgfplots}
\usepackage{hyperref}
\usepackage{graphicx}
\usepackage{amsmath}
\usepackage{cancel}
%% For tabular environment
\usepackage[T1]{fontenc}
\usepackage{makecell}
\usetikzlibrary{calc} 
\usepackage{tkz-euclide}
\usetkzobj{all}

\begin{document}
\pagestyle{empty}
\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

    \begin{tikzpicture}[thick,scale=1.3]
        \tkzDefPoint(0,0){P}
        \tkzDefPoint(70:3){Q}
        \tkzDefSquare(P,Q) \tkzGetPoints{R}{S}

        \tkzInterLL(P,R)(Q,S)  \tkzGetPoint{O}

        \tkzLabelPoints[below](P)
        \tkzLabelPoints[right](Q)
        \tkzLabelPoints[above](R)
        \tkzLabelPoints[left](S)

        \tkzMarkAngle[size=0.8,draw=none, fill=lightblue](P,S,Q)
        %\tkzMarkAngle[size=1.4,draw=none, fill=lightblue](D,B,A)

        \tkzLabelAngle[pos=1.45](P,S,Q){$(2t+7)^\circ$};
        %\tkzLabelAngle[pos=2, yshift=-0.15cm](A,B,D){${(x+15)}^\circ$};

        \tkzDrawSquare[very thick](P,Q)
        \tkzDrawSegments[dashed, thin, black!80](Q,S)

    \end{tikzpicture}
\end{document}

